    COMPREPLY=()
    cur="${COMP_WORDS[COMP_CWORD]}"
    prev="${COMP_WORDS[COMP_CWORD-1]}"
    cmd=""
    opts=""

    for i in ${COMP_WORDS[@]}
    do
        case "${cmd},${i}" in
            ",$1")
                cmd="rolr"
                ;;
            rolr,add)
                cmd="rolr__add"
                ;;
            rolr,complete)
                cmd="rolr__complete"
                ;;
            rolr,help)
                cmd="rolr__help"
                ;;
            rolr,list)
                cmd="rolr__list"
