            rolr__help,update)
                cmd="rolr__help__update"
                ;;
            *)
                ;;
        esac
    done

    case "${cmd}" in
        rolr)
            opts="-v -q -h -V --verbose --quiet --help --version add select update list run complete help"
            if [[ ${cur} == -* || ${COMP_CWORD} -eq 1 ]] ; then
                COMPREPLY=( $(compgen -W "${opts}" -- "${cur}") )
                return 0
            fi
            case "${prev}" in
                *)
                    COMPREPLY=()
                    ;;
            esac
            COMPREPLY=( $(compgen -W "${opts}" -- "${cur}") )
            return 0
            ;;
        rolr__add)
            opts="-v -q -h -V --verbose --quiet --help --version [ROLES]..."
