if [[ "${BASH_VERSINFO[0]}" -eq 4 && "${BASH_VERSINFO[1]}" -ge 4 || "${BASH_VERSINFO[0]}" -gt 4 ]]; then
    complete -F _rolr -o nosort -o bashdefault -o default rolr
else
    complete -F _rolr -o bashdefault -o default rolr
fi
